const sid = String($env.N8N_GS_BACKUP_SPREADSHEET || $env.BACKUP_SPREADSHEET || '').trim();
const sheet = String($env.N8N_GS_BACKUP_SHEET || $env.BACKUP_SHEET || 'Respaldo_Sensores').trim();
const rows = [
  ['ts', 'tabla', 'filas'],
  [new Date().toISOString(), String($env.N8N_DB_COSECHAS || 'castuo_prod_cosechas'), '0'],
];
const report_hash = require('crypto')
  .createHash('sha256')
  .update(JSON.stringify(rows))
  .digest('hex');
return [
  {
    json: {
      spreadsheetId: sid,
      sheetName: sheet,
      values: rows,
      report_hash,
      note: 'Añadir nodo Google Sheets (OAuth2) operation append/update con credencial. No exponer refresh token en JSON exportado.',
    },
  },
];
